from __future__ import absolute_import
import shutil
import tempfile
import os
from pyvirtualdisplay import Display
from taf.ul.oam.selenium_rap_manager.tools import format_ip_address_if_ipv6
from taf.ul.oam.selenium_core.download_tools import Downloader
from taf.ul.oam.selenium_core.webdrivers import CustomWebdriver
from taf.ul.oam.selenium_rap_manager.login_page import LoginPage
from taf.ul.oam.selenium_rap_manager.logout import Logout
from taf.ul.oam.selenium_rap_manager.certificates_page import Certificates
from taf.ul.oam.selenium_rap_manager.common import catch_interface_exception, Debug
from taf.ul.oam.selenium_rap_manager.tools_page import Tool
from taf.ul.oam.selenium_rap_manager.network_page import Network
from taf.ul.oam.selenium_rap_manager.rap_page import RAP


class rap_manager(object):
    """
    Keywords for megazone
    ..note:: selenium_rap_manager lib requires display drivers to be installed
    at the machine on which tests are run. If one needs run tests without
    display options should install xvfb tool at the machine.
    """

    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'
    ROBOT_LISTENER_API_VERSION = 2

    def __init__(self):
        self.page = None
        self.__driver = None
        self._download_dir = None
        self._tmp_download_dir = False
        self._debug_dir = None
        self._url = None
        self._username = None
        self._password = None
        self._display = None
        self.downloader = Downloader()

    @property
    def download_dir(self):
        """ Get download directory path.
        If path was not provided, function returns path to temporary directory,
        which will be removed during logout. """
        return self.get_download_dir()

    def get_download_dir(self):
        """ Function for compatibility with robot framework.  See download_dir property. """
        if self._download_dir is None:
            self._download_dir = tempfile.mkdtemp(suffix="ta_rap_manager")
            self._tmp_download_dir = True
        return self._download_dir

    @download_dir.setter
    def download_dir(self, download_dir):
        """ Set download directory path.
        Note that this function can be called only before driver initialization.

        :param download_dir: path to download dir
        """
        self.set_download_dir(download_dir)

    def set_download_dir(self, download_dir):
        """ Function for compatibility with robot framework. See download_dir property. """
        if self.__driver is None:
            self._download_dir = download_dir
        else:
            raise AttributeError("Download dir must be set before initialization of "
                                 "driver (in most cases before login keyword)")

    @property
    def debug_dir(self):
        return self.get_debug_dir()

    def get_debug_dir(self):
        if self._debug_dir is None:
            self._debug_dir = tempfile.mkdtemp(suffix="ta_rap_manager_debug")
        return self._debug_dir

    @debug_dir.setter
    def debug_dir(self, download_dir):
        self.set_download_dir(download_dir)

    def set_debug_dir(self, debug_dir):
        self._debug_dir = os.path.join(debug_dir, "ta_rap_manager_debug")
        if not os.path.exists(self._debug_dir):
            os.makedirs(self._debug_dir)

    @property
    def _driver(self):
        if self.__driver is None:
            self.__driver = CustomWebdriver(self.download_dir)
        return self.__driver

    def enable_virtual_display(self, width=1920, height=1280):
        """
        This keyword is used to enable virtual display - with it enabled browser
        window will not be displayed on screen.

        In order for this functionality to work correctly this keyword must to be
        called before `Login` keyword is called (which would spawn browser window).

        Please make sure "xvfb" service is installed on the environment.

        :param width: int, width of browser
        :param height: int, height of browser
        """
        self._display = Display(visible=0, size=(width, height))
        self._display.start()

    def disable_virtual_display(self):
        """
        This keyword is used to disable virtual display.
        Please make sure to call this method at the end of test if you've call "enable_virtual_display"
        """
        self._display.stop()

    @catch_interface_exception
    def login(self, url, username, password, after_reset=False):
        """
        Login into megazone bts.
        :param url: url to megazone management system
        :param username: username
        :param password: password
        :param after_reset: allow login to fail. New vesions of software performs login automatically.
        """
        url = format_ip_address_if_ipv6(url)
        self._driver.get(url)
        self._url = url
        self._username = username
        self._password = password
        self.page = LoginPage(self._driver)
        self.page = self.page.login(username, password, after_reset)

    @catch_interface_exception
    def logout(self):
        """
        Closes browser and remove contents of download dir if download dir path was not provided.
        """
        if self._tmp_download_dir:
            shutil.rmtree(self.download_dir)
            self._tmp_download_dir = False
            self._download_dir = None

        if self.__driver is None:
            return

        Logout(self.__driver).logout_and_exit_browser()
        self.__driver = None

    @catch_interface_exception
    def install_certificate(self, file_path, password):
        return Certificates(self._driver).install_certificate(file_path, password)

    @catch_interface_exception
    def update_certificate_revocation_list(self, crl_update_interval=24, crl_source='Certificates',
                                           distribution_list=[[]]):
        """
        steps:
        1） Go to Certificate Revocation Lists
        2） select the button "Enable CRL"
        3） configure the CRL parameters
        4） configure Additional CRL distribution points: [[1, 2], [None, 4], [5, 6]]
        5） Click the button "Update"

        Certificates
        Manual configuration
        Certificates and manual configuration
        :return: Str, revocation list update status
        """
        return Certificates(self._driver).update_certificate_revocation_list(crl_update_interval, crl_source,
                                                                             distribution_list)

    @catch_interface_exception
    def get_cert_detail(self, field=None, root_type='TA', root_type_index=1, target_level=1):
        """
        Check certificate info at BTS Certificates tab
        :param field: str, certificate field
        :param root_type: every certificate record can be a tree which has 3 levels or less.
                          root_type is the top node's type name of target row's tree.
                          in the top level type name like 'TA'
        :param root_type_index: index of same root_type names in table.
               e.g. second 'TA', root_type_index = 2. root_type_index start from 1.
        :param target_level: target_level in selected tree node.
               e.g. tree node is "TA"->"CA"->"BTS", target row is BTS, target_level should be 3
                    target_level start from 1.
        :return: dict, if field is not none, specific value according to filed will be returned
        """
        return Certificates(self._driver).get_cert_detail(field, root_type, root_type_index, target_level)

    @catch_interface_exception
    def initialize_certificates(self, ip, ca_subject_name, ref_num, pre_shared_key, port=1024, directory='pkix',
                                timeout=60):
        return Certificates(self._driver).initialize_certificates(ip, port, directory, ca_subject_name, ref_num,
                                                                  pre_shared_key, timeout)

    def save_screenshot(self, filename, screenshot_dir=None):
        """
        Keyword for save screen shot, tester can add this keyword after failed test case to provide clues for developer
        :param filename: str, png file name, please keep it unique
        :param screenshot_dir: str or None, screen shot path, user should have permission to read and write this dir
        """
        screenshot_dir = screenshot_dir if screenshot_dir else self.debug_dir
        Debug(self._driver).save_screenshot(filename, screenshot_dir)

    def enable_restricted_root_access(self):
        """
        enables restricted root access under tools tab of RAP
        """
        Tool(self._driver).enable_restricted_root_access()

    def disable_restricted_root_access(self):
        """

        Disables restricted root access under tools tab of RAP
        """
        Tool(self._driver).disable_restricted_root_access()

    def enable_ethernet_port_security(self):
        """
        enables ethernet port security under tools tab of RAP
        """
        Tool(self._driver).enable_ethernet_port_security()

    def disable_ethernet_port_security(self):
        """
        disables ethernet port security under tools tab of RAP
        """
        Tool(self._driver).disable_ethernet_port_security()

    def enable_service_account_ssh(self):
        """
        enables service account ssh status under tools tab of RAP
        """
        Tool(self._driver).enable_service_account_ssh()

    def disable_service_account_ssh(self):
        """
        disables service account ssh status under tools tab of RAP
        """
        Tool(self._driver).disable_service_account_ssh()

    def enable_service_port(self):
        """
        enables service port status under tools tab of RAP
        """
        Tool(self._driver).enable_service_port()

    def disable_service_port(self):
        """
        disables service port status under tools tab of RAP
        """
        Tool(self._driver).disable_service_port()

    def configure_network(self, ip_address, prefix_length, vlan_id=None, static_routes_update_list=[],
                          static_routes_delete_list=[], static_routes_add_list=[]):
        """
        configure network
        :param ip_address: str, ip_address, required
        :param prefix_length: str, prefix_length, required
        :param vlan_id: int or None, optinal, vlan id
        :param static_routes_update_list: dict list of to be updated,like: [{index: 1, ip:'', prefix: '2',gate_way:'2'}]
        :param static_routes_delete_list: dict list of to be deleted,like: [{identify:'10.76.163.0:24:10.57.152.189'}]
        :param static_routes_add_list: dict list of to be updated,like: [{ip:'3.3.3.3', prefix: '2',gate_way:'2'}]
         """
        return Network(self._driver).configure_network(ip_address, prefix_length, vlan_id, static_routes_update_list,
                                                       static_routes_delete_list, static_routes_add_list)

    def get_software_info(self):
        """
        get the software infomation under RAP tab
        :return: dict, {'active_package':xxx, 'passive_package':xxx, 'running_package':xxx, 'active_sw_version':xxx, 'passive_sw_version':xxx}
        """
        return RAP(self._driver).get_software_infomation()
